//! Per-vertex texture coordinates against OpenSKP's Python reader: for textured faces
//! of corpus files, `openskp._face_groups.compute_face_uv` with `face_uv_basis` of the
//! face normal, the face's `uv_transform` (front or back) and the material texture's
//! tile size (generated by a small script over `SkpFile.parse()`; the first four
//! outer-loop vertices of the first pinned and default-projected faces).

use mt_skp::Model;
use mt_skp::uv::UvMapping;

fn open(name: &str) -> Model {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/corpus/openskp")
        .join(name);
    mt_skp::read(&path).unwrap_or_else(|e| panic!("{name}: {e}"))
}

/// (face id, back side, vertex id, u, v)
type Expected = (i64, bool, i64, f64, f64);

fn check(name: &str, expected: &[Expected]) {
    let m = open(name);
    let materials: std::collections::HashMap<_, _> = m.materials_by_id().collect();
    let defs: Vec<_> = m.definitions.values().chain([&m.root]).collect();
    let mut pinned = 0;
    for &(face_id, back, vertex_id, u, v) in expected {
        let (d, f) = defs
            .iter()
            .find_map(|d| d.faces.get(&face_id).map(|f| (d, f)))
            .unwrap_or_else(|| panic!("{name}: face {face_id}"));
        let (material, transform) = if back {
            (f.back_material_id, f.uv_transform_back.as_ref())
        } else {
            (f.material_id, f.uv_transform.as_ref())
        };
        pinned += usize::from(transform.is_some());
        let texture = material
            .and_then(|i| materials.get(&i))
            .and_then(|m| m.texture.as_ref())
            .unwrap_or_else(|| panic!("{name}: face {face_id} is not textured"));
        let n = f.normal.expect("face normal");
        let p = &d.vertices[&vertex_id];
        let mapping = UvMapping::new(n, transform, [texture.width, texture.height]);
        let got = mapping.uv([p.x, p.y, p.z]);
        let close = |a: f64, b: f64| (a - b).abs() <= 1e-9 * (1.0 + b.abs());
        assert!(
            close(got[0], u) && close(got[1], v),
            "{name}: face {face_id} back={back} vertex {vertex_id}: {got:?} != [{u}, {v}]"
        );
    }
    assert!(pinned > 0, "{name}: no positioned texture checked");
}

